(function () {
  function escapeHtml(value) {
    return String(value ?? "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  function inline(text) {
    return escapeHtml(text)
      .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
      .replace(/`([^`]+)`/g, "<code>$1</code>");
  }

  function isTableSeparator(line) {
    return /^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(line);
  }

  function parseTable(lines, start) {
    const rows = [];
    let index = start;
    while (index < lines.length && /\|/.test(lines[index]) && lines[index].trim()) {
      if (!isTableSeparator(lines[index])) rows.push(lines[index]);
      index += 1;
    }
    if (rows.length < 2) return null;
    const cells = rows.map((row) => row.replace(/^\||\|$/g, "").split("|").map((cell) => cell.trim()));
    const header = cells.shift();
    const body = cells;
    const html = `
      <div class="table-scroll">
        <table>
          <thead><tr>${header.map((cell) => `<th>${inline(cell)}</th>`).join("")}</tr></thead>
          <tbody>${body.map((row) => `<tr>${row.map((cell) => `<td>${inline(cell)}</td>`).join("")}</tr>`).join("")}</tbody>
        </table>
      </div>
    `;
    return { html, next: index };
  }

  function parse(markdown) {
    const lines = String(markdown || "").replace(/\r\n/g, "\n").split("\n");
    const output = [];
    let index = 0;
    while (index < lines.length) {
      const line = lines[index];
      if (!line.trim()) {
        index += 1;
        continue;
      }
      if (line.startsWith("```")) {
        const code = [];
        index += 1;
        while (index < lines.length && !lines[index].startsWith("```")) {
          code.push(lines[index]);
          index += 1;
        }
        index += 1;
        output.push(`<pre><code>${escapeHtml(code.join("\n"))}</code></pre>`);
        continue;
      }
      if (index + 1 < lines.length && /\|/.test(line) && isTableSeparator(lines[index + 1])) {
        const table = parseTable(lines, index);
        if (table) {
          output.push(table.html);
          index = table.next;
          continue;
        }
      }
      if (/^#{1,3}\s+/.test(line)) {
        const level = Math.min(3, line.match(/^#+/)[0].length);
        output.push(`<h${level}>${inline(line.replace(/^#{1,3}\s+/, ""))}</h${level}>`);
        index += 1;
        continue;
      }
      if (/^\s*[-*]\s+/.test(line)) {
        const items = [];
        while (index < lines.length && /^\s*[-*]\s+/.test(lines[index])) {
          items.push(lines[index].replace(/^\s*[-*]\s+/, ""));
          index += 1;
        }
        output.push(`<ul>${items.map((item) => `<li>${inline(item)}</li>`).join("")}</ul>`);
        continue;
      }
      const paragraph = [line];
      index += 1;
      while (index < lines.length && lines[index].trim() && !/^#{1,3}\s+/.test(lines[index]) && !/^\s*[-*]\s+/.test(lines[index]) && !lines[index].startsWith("```")) {
        if (index + 1 < lines.length && /\|/.test(lines[index]) && isTableSeparator(lines[index + 1])) break;
        paragraph.push(lines[index]);
        index += 1;
      }
      output.push(`<p>${inline(paragraph.join(" "))}</p>`);
    }
    return output.join("");
  }

  window.marked = { parse };
})();
